insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('f72347d9-a04c-5ee8-ad9b-7cce5b614929', 'rg5-word-parts-p06', (select id from public.skills where slug = 'read-g5-word-parts'), null,
        '3-5', $q$Grandpa Teo's Story$q$, $q$For her class project, Mei had to write about a family member's life. She chose her grandpa, Teo, who had moved to this country when he was eleven.

Grandpa Teo opened a dusty box of old photographs. One showed him as a boy standing beside a fishing boat. "That was my village," he said. He pulled out a map and pointed to a green island far across the ocean.

Mei had studied geography that year, so she knew the island's name and that it was surrounded by warm water. Grandpa smiled. "You know more about my home than some of my old friends do!"

Grandpa Teo had once started writing his autobiography in a notebook. But his handwriting had become shaky, and many pages were barely legible. So he dictated his memories, and Mei typed every word on her laptop.

When she finished, Mei titled her project "The Boy from the Green Island." She gave her grandpa the first printed copy. He read it slowly and said it was the best gift he had ever received.$q$, 'draft')
